/** Loads mcp-server/driftara/catalog.json (generated by scripts/build_driftara_catalog.mjs) and resolves ids. */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import type { DriftaraCatalogFile, DriftaraRecord } from "./types.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
/** dist/driftara/catalog.js -> mcp-server/driftara/catalog.json */
export const CATALOG_PATH = path.resolve(__dirname, "..", "..", "driftara", "catalog.json");

export class DriftaraCatalog {
    readonly actions: DriftaraRecord[];
    readonly fieldWeights: Record<string, number>;
    private readonly byId = new Map<string, DriftaraRecord>();
    private readonly byAlias = new Map<string, DriftaraRecord>();

    constructor(file: DriftaraCatalogFile) {
        this.actions = file.actions;
        this.fieldWeights = file.field_weights;
        for (const a of this.actions) this.byId.set(a.action_id, a);
        // Legacy tool names, raw IPC channels and other aliases; the first record wins.
        for (const a of this.actions) {
            for (const key of [a.legacy_tool_name, ...(a.executor.kind === "ipc" ? [a.executor.channel] : [])]) {
                if (key && !this.byAlias.has(key)) this.byAlias.set(key, a);
            }
        }
    }

    get(actionId: string): DriftaraRecord | undefined {
        return this.byId.get(actionId);
    }

    /** exact id -> legacy tool name / raw IPC channel -> last dotted segment as legacy name -> unique suffix. */
    resolveId(needle: string): DriftaraRecord | undefined {
        const q = needle.trim();
        if (!q) return undefined;
        const exact = this.byId.get(q) ?? this.byAlias.get(q);
        if (exact) return exact;
        if (q.includes(".")) {
            const last = this.byAlias.get(q.slice(q.lastIndexOf(".") + 1));
            if (last) return last;
        }
        const suffix = this.actions.filter((a) => a.action_id.endsWith(`.${q}`));
        return suffix.length === 1 ? suffix[0] : undefined;
    }

    counts(): Record<string, Record<string, number>> {
        const out: Record<string, Record<string, number>> = {};
        for (const a of this.actions) {
            out[a.source] ??= { read: 0, write: 0, destructive: 0, total: 0 };
            out[a.source][a.tier] += 1;
            out[a.source].total += 1;
        }
        return out;
    }
}

let cached: DriftaraCatalog | null = null;

export function loadCatalog(file = CATALOG_PATH): DriftaraCatalog {
    if (cached && file === CATALOG_PATH) return cached;
    const parsed = JSON.parse(fs.readFileSync(file, "utf-8")) as DriftaraCatalogFile;
    const catalog = new DriftaraCatalog(parsed);
    if (file === CATALOG_PATH) cached = catalog;
    return catalog;
}
